mapper.select:
select t1.*, t1.un_write_off_amount_pre - nvl((SELECT SUM(tt.transaction_amount) FROM csh_transaction tt WHERE tt.source_doc_id = t1.advance_csh_trx_id AND tt.transaction_type = 'REFUND'), 0) AS un_write_off_amount, (case when (select count(1) from csh_transaction cs where cs.source_doc_id=t1.advance_csh_trx_id AND cs.transaction_type = 'REFUND' )=0 then 'N' else 'Y' end) refund_flag, (case when (select count(1) from csh_transaction cs where cs.source_doc_id=t1.advance_csh_trx_id AND cs.transaction_type = 'REFUND' )=0 then '否' else '是' end) refund_flag_n, nvl((SELECT SUM(cs.transaction_amount) FROM csh_transaction cs WHERE cs.source_doc_id = t1.advance_csh_trx_id AND cs.transaction_type = 'REFUND'), 0) AS refund_amount, ( SELECT NVL(sum(ctr.REFUND_AMOUNT), 0) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVING' AND ctr.TRANSACTION_ID = t1.TRANSACTION_ID ) refunding_amount from (select ttt.*, cb.bank_name, car.receipt_id,car.allocation_id,car.advance_receipt_amount
from (select t.*, (case when t.reversed_flag ='N' then '否' else '是' end) reversed_flag_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'WRITE_OFF_FLAG' AND v.code_value = t.write_off_flag) write_off_flag_desc, ( CASE WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.csh_transaction_id = t.transaction_id) = 0 THEN 'NOT' WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.write_flag = 'N' AND com.csh_transaction_id = t.transaction_id) > 0 THEN 'NEW' WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.write_flag = 'R' AND com.csh_transaction_id = t.transaction_id) > 0 THEN 'REJECT' ELSE 'CHECK' END ) match_status, hbm.bp_name, nvl(t.transaction_amount, 0) - nvl(t.write_off_amount, 0) AS un_write_off_amount_pre, cba.bank_account_name, cba.bank_account_num, (nvl(t.transaction_amount, 0) - nvl((SELECT SUM(nvl(wo.csh_write_off_amount, 0)) FROM csh_write_off wo WHERE wo.csh_transaction_id = t.transaction_id AND wo.reversed_flag = 'N' AND (wo.write_off_type != 'REFUND' or wo.write_off_type = 'REFUND')), 0)) can_return_amount, (select o.subsequent_csh_trx_id from csh_write_off o where o.csh_transaction_id = t.transaction_id AND o.write_off_type = 'RECEIPT_ADVANCE_RECEIPT' AND o.reversed_flag = 'N' and rownum=1) as advance_csh_trx_id, cba.bank_id FROM csh_transaction t LEFT JOIN csh_bank_account cba on cba.bank_account_id = t.bank_account_id LEFT JOIN hls_bp_master hbm on hbm.bp_id = t.bp_id) ttt INNER JOIN csh_allocation_receipt car ON car.transaction_id = ttt.transaction_id LEFT JOIN csh_bank cb ON cb.bank_id = ttt.bank_id ) t1
1=1
and t1.allocation_id = #{allocationId}
and t1.transaction_id = #{transactionId}
order by t1.receipt_id
